  uploadSupplierPrice: {
    parameters: {
      query?: never
      header?: {
        /**
         * @description Client-generated key (UUID recommended). Stored as `imports.idempotency_key`, unique per shop and
         *     kept as long as the import row (no TTL). A repeat with the same key returns the existing import
         *     with 200 and does not count against the rate limit.
         */
        'Idempotency-Key'?: components['parameters']['IdempotencyKeyOptional']
      }
      path: {
        /** @description Supplier id (UUID v7). */
        supplier_id: components['parameters']['SupplierId']
      }
      cookie?: never
    }
    requestBody: {
      content: {
        /**
         * @example {
         *       "file": "<binary price.xlsx>",
         *       "column_mapping": {
         *         "columns": [
         *           {
         *             "header": "Код",
         *             "role": "supplier_code"
         *           },
         *           {
         *             "header": "Найменування",
         *             "role": "name"
         *           },
         *           {
         *             "header": "EAN",
         *             "role": "barcode"
         *           },
         *           {
         *             "header": "Ціна",
         *             "role": "price"
         *           },
         *           {
         *             "header": "Залишок",
         *             "role": "stock_quantity"
         *           },
         *           {
         *             "header": "Примітка",
         *             "role": null
         *           }
         *         ]
         *       }
         *     }
         */
        'multipart/form-data': components['schemas']['PriceUpload']
      }
    }
    responses: {
      /** @description Idempotent replay — the existing import with this `Idempotency-Key`. */
      200: {
        headers: {
          [name: string]: unknown
        }
        content: {
          'application/json': components['schemas']['Import']
        }
      }
      /** @description Import queued. Poll `getImport` for `applied`, `rejected` or `awaiting_mapping`. */
      202: {
        headers: {
          [name: string]: unknown
        }
        content: {
          'application/json': components['schemas']['Import']
        }
      }
      401: components['responses']['Unauthenticated']
      404: components['responses']['SupplierNotFound']
      413: components['responses']['FileTooLarge']
      415: components['responses']['UnsupportedMediaType']
      422: components['responses']['InvalidColumnMapping']
      429: components['responses']['RateLimited']
      500: components['responses']['Internal']
    }
  }
  fetchSupplierFeed: {
    parameters: {
      query?: never
      header: {
        /**
         * @description Mandatory (SAD §6 US-02: the fetch job retries up to 3 times). Becomes the `request_id` part of the
         *     import idempotency key `supplier_id + request_id`, unique per shop and kept with the import row.
         *     Must be at most 160 characters so the composed key fits `VARCHAR(200)`.
         */
        'Idempotency-Key': components['parameters']['IdempotencyKeyRequired']
      }
      path: {
        /** @description Supplier id (UUID v7). */
        supplier_id: components['parameters']['SupplierId']
      }
      cookie?: never
    }
    requestBody?: never
    responses: {
      /** @description Fetch queued (also on replay of the same key). */
      202: {
        headers: {
          [name: string]: unknown
        }
        content: {
          /**
           * @example {
           *       "supplier_id": "0199a3c1-5e6f-7b20-8c31-4d5e6f708192",
           *       "idempotency_key": "2b7c1e0a-4f7d-4c55-9d0e-1a2b3c4d5e6f"
           *     }
           */
          'application/json': components['schemas']['FeedFetchAccepted']
        }
      }
      401: components['responses']['Unauthenticated']
      404: components['responses']['SupplierNotFound']
      409: components['responses']['FeedNotConfigured']
      422: components['responses']['ValidationFailed']
      500: components['responses']['Internal']
    }
  }
